

import datetime as dt
import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel


class UsageEventsData(UniversalBaseModel):
    billable_events: typing.Optional[int] = pydantic.Field(default=None)
    """
    Events that are billable, this include all events except platform events
    """

    device: typing.Optional[str] = None
    fleet: typing.Optional[str] = None
    notefiles: typing.Optional[typing.Dict[str, int]] = pydantic.Field(default=None)
    """
    Count of events per notefile. Only present when includeNotefiles=true is specified.
    """

    period: dt.datetime
    platform_events: int = pydantic.Field()
    """
    Total platform events. Platform events are _log, _session, _health, and _geolocate events some of which are send from the device, some generated by notehub. These events are not billed.
    """

    total_days_in_period: typing.Optional[int] = pydantic.Field(default=None)
    """
    The total number of days in this period. Useful for calculating daily averages for month period. Note that the current period will be the total number of days in the current period, including days in the future.
    """

    total_devices: int = pydantic.Field()
    """
    Total devices represented in this count
    """

    total_events: int = pydantic.Field()
    """
    Total events the device sent to notehub, including associated notehub generated events
    """

    total_fw_updates: typing.Optional[int] = pydantic.Field(default=None)
    """
    Number of firmware updates in this period (from _health.qo DFU events)
    """

    total_reboots: typing.Optional[int] = pydantic.Field(default=None)
    """
    Number of device reboots in this period (from _health.qo boot events)
    """

    watchdog_events: int = pydantic.Field()
    """
    Watchdog events are events generated by notehub when a watchdog timer is configured for a device to indicate is has not been online for a period of time. These events are billed but should not be used to indicate a device is active, or connected, at this time.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
